<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{monthlyContractApi}from'../api';import type{MonthlyContract}from'../types';import BaseStatusBadge from'@/components/common/BaseStatusBadge.vue';const route=useRoute(),router=useRouter(),contract=ref<MonthlyContract|null>(null),loading=ref(true),error=ref('');async function load(){try{contract.value=await monthlyContractApi.get(Number(route.params.id))}catch(e:any){error.value=e?.response?.data?.message||'Unable to load contract.'}finally{loading.value=false}}async function remove(){if(!contract.value||!window.confirm('Delete this contract? Contracts with renewal history cannot be deleted.'))return;try{await monthlyContractApi.remove(contract.value.id);await router.push('/monthly-contracts')}catch(e:any){error.value=e?.response?.data?.message||'Unable to delete contract.'}}onMounted(load)</script>
<template><main class="fleet-module page-content"><div class="page-heading"><div v-if="contract" class="d-flex flex-wrap gap-2"><RouterLink v-if="contract.status!=='Renewed'&&contract.status!=='Cancelled'" :to="`/monthly-contracts/${contract.id}/edit`" class="btn btn-outline-primary">Edit</RouterLink><RouterLink v-if="contract.status!=='Renewed'&&contract.status!=='Cancelled'&&!(contract.renewals?.length)" :to="`/monthly-contracts/${contract.id}/renew`" class="btn btn-outline-warning">Renew</RouterLink><button class="btn btn-outline-danger" @click="remove">Delete</button><RouterLink to="/monthly-contracts" class="btn btn-outline-secondary">Back</RouterLink></div></div><div v-if="error" class="alert alert-danger">{{error}}</div><div v-if="loading" class="alert alert-light border">Loading contract…</div><template v-else-if="contract"><div class="row g-3"><div class="col-lg-8"><section class="card shadow-sm h-100"><div class="card-header bg-white d-flex justify-content-between"><h2 class="h5 mb-0">{{contract.contract_no}}</h2><BaseStatusBadge :status="contract.status"/></div><div class="card-body"><dl class="row mb-0"><dt class="col-sm-4">Customer</dt><dd class="col-sm-8">{{contract.customer_name}}<span v-if="contract.guest_name"> · {{contract.guest_name}}</span></dd><dt class="col-sm-4">Contact</dt><dd class="col-sm-8">{{contract.contact_person||'—'}} · {{contract.customer_phone||'—'}}</dd><dt class="col-sm-4">Monthly vehicle</dt><dd class="col-sm-8">{{contract.car?.plate_no||'—'}} <span v-if="contract.car">· {{contract.car.model_name}}</span></dd><dt class="col-sm-4">Monthly driver</dt><dd class="col-sm-8">{{contract.driver?.full_name||'—'}}</dd><dt class="col-sm-4">Operator</dt><dd class="col-sm-8">{{contract.operator_name||'—'}}</dd><dt class="col-sm-4">Assignment</dt><dd class="col-sm-8">{{contract.assignment_type}}</dd><dt class="col-sm-4">Period</dt><dd class="col-sm-8">{{contract.start_date}} to {{contract.end_date}}</dd><dt class="col-sm-4">Monthly rate</dt><dd class="col-sm-8">{{contract.rental_currency}} {{contract.monthly_rate}} · {{contract.rental_status}}</dd><dt class="col-sm-4">Contract insurance snapshot</dt><dd class="col-sm-8">{{contract.insurance_price}} · {{contract.insurance_company||'—'}}</dd><dt class="col-sm-4">Terms / notes</dt><dd class="col-sm-8">{{contract.terms_conditions||contract.note||'—'}}</dd></dl></div></section></div><div class="col-lg-4"><section class="card shadow-sm h-100"><div class="card-header bg-white"><h2 class="h5 mb-0">Renewal history</h2></div><div class="card-body"><RouterLink v-if="contract.renewal_parent" :to="`/monthly-contracts/${contract.renewal_parent.id}`">Previous: {{contract.renewal_parent.contract_no}}</RouterLink><p v-else>This is the original contract.</p><ul v-if="contract.renewals?.length" class="list-group list-group-flush"><li v-for="r in contract.renewals" :key="r.id" class="list-group-item px-0"><RouterLink :to="`/monthly-contracts/${r.id}`">{{r.contract_no}}</RouterLink><div class="small text-muted">{{r.start_date}} to {{r.end_date}}</div></li></ul><p v-else class="text-muted mb-0">No renewal has been recorded.</p></div></section></div></div><section class="card shadow-sm mt-3"><div class="card-header bg-white"><h2 class="h5 mb-0">Contract snapshot</h2></div><div class="card-body"><div class="row"><div class="col-md-4"><strong>Prepared by</strong><div>{{contract.prepared_by||'—'}}</div></div><div class="col-md-4"><strong>Invoice sender</strong><div>{{contract.invoice_sender||'—'}}</div></div><div class="col-md-4"><strong>Checked by</strong><div>{{contract.checked_by||'—'}}</div></div><div class="col-md-4 mt-3"><strong>Off day / service hours</strong><div>{{contract.off_day||'—'}} / {{contract.service_hour||'—'}}</div></div><div class="col-md-4 mt-3"><strong>Operation sheet</strong><div>{{contract.operation_sheet||'—'}}</div></div><div class="col-md-4 mt-3"><strong>Even / odd</strong><div>{{contract.even_odd||'—'}}</div></div></div></div></section></template><div v-else-if="!loading" class="alert alert-warning">Contract is unavailable.</div></main></template>
